  id: string;
  type?: string;
  content?: string;
  tokens?: number;
  [key: string]: unknown;
}

export interface PairedAblationCase {
  id: string;
  insertions: PairedAblationItem[];
  expectedRetained?: string[];
  passAtK?: number[];
  tokensProxy?: number;
  falseIntercepts?: number;
  safetyViolations?: number;
}

export interface PairedAblationFixture {
  schemaVersion: number;
  preregistration: {
    primaryMetric: string;
    regressionBudget: Array<{ metric: string; maximumRegression: number }>;
    metrics?: Array<{ id: string; direction: 'higher' | 'lower' }>;
  };
  cases: PairedAblationCase[];
}

export interface RuntimeStoreAdapter {
  insert(store: unknown, item: PairedAblationItem): Promise<unknown> | unknown;
  listRetained(store: unknown): Promise<Iterable<string> | string[]> | Iterable<string> | string[];
}

export interface EvictionAdapter {
  baseline(store: unknown, item: PairedAblationItem, context: { seed: number }): Promise<unknown> | unknown;
  treatment(store: unknown, item: PairedAblationItem, context: { seed: number }): Promise<unknown> | unknown;
}

export interface PairedAblationOptions {
  fixture?: PairedAblationFixture;
  fixturePath?: string;
  createStore(context: { isolated: true; seed: number; condition: 'baseline' | 'treatment' }): Promise<unknown> | unknown;
  insert: RuntimeStoreAdapter['insert'];
  listRetained: RuntimeStoreAdapter['listRetained'];
  eviction: EvictionAdapter;
  repetitions: number;
  seed: number;
  clock?: { now(): number };
}

export interface MetricSummary {
  direction: 'higher' | 'lower';
  baseline: { n: number; mean: number; p50: number; p95: number };
  treatment: { n: number; mean: number; p50: number; p95: number };
  pairedEffect: {
    definition: string;
    meanDelta: number;
    medianDelta: number;
    confidence95: [number, number];
    standardizedEffect: number;
    favorable: boolean;
    interpretation: string;
  };
}

export interface PairedAblationResult {
  schemaVersion: 1;
  experiment: string;
  fixtureSha256: string;
  seed: number;
  repetitions: number;
  caseCount: number;
  conditions: ['baseline', 'treatment'];
  componentObserved: true;
  preregistration: PairedAblationFixture['preregistration'];
  metrics: Record<string, MetricSummary>;
  observations: unknown[];
  notes: string[];
}

export function runPairedAblation(options: PairedAblationOptions): Promise<PairedAblationResult>;
export function loadFixture(path?: string): Promise<PairedAblationFixture>;
export function summarize(observations: unknown[], preregistration?: PairedAblationFixture['preregistration']): Record<string, MetricSummary>;
export function deriveSeed(seed: number, caseIndex: number, repetition: number): number;
