import { createHash } from 'node:crypto';

const DEFAULT_FIXTURE = 'shared/agent-dev/paired-ablation-fixture.json';

/**
 * Run a paired, leave-one-out ablation against a real RuntimeMemoryStore.
 *
 * The store and eviction implementations are injected so this harness cannot
 * silently replace the runtime with a simulation.  `baseline` and `treatment`
 * must use the same store factory and differ only by the eviction component.
 */
export async function runPairedAblation(options) {
  validateOptions(options);
  const fixture = options.fixture ?? await loadFixture(options.fixturePath ?? DEFAULT_FIXTURE);
  const cases = fixture.cases;\n  const conditions = ['baseline', 'treatment'];
  const observations = [];

  for (let caseIndex = 0; caseIndex < cases.length; caseIndex += 1) {
    const fixtureCase = cases[caseIndex];
    const paired = [];
    for (let repetition = 0; repetition < options.repetitions; repetition += 1) {
      const conditionResults = {};
      for (const condition of conditions) {
        const seed = deriveSeed(options.seed, caseIndex, repetition);
        conditionResults[condition] = await runCondition({
          ...options,
          condition,
          fixtureCase,
          caseIndex,
          repetition,
          seed
        });
      }
      const retainedDifference = difference(conditionResults.baseline.retained, conditionResults.treatment.retained);
      const evictedDifference = difference(conditionResults.baseline.evicted, conditionResults.treatment.evicted);
      paired.push({
        caseId: fixtureCase.id,
        repetition,
        seed,
        baseline: conditionResults.baseline,
        treatment: conditionResults.treatment,
        componentObserved: retainedDifference.length > 0 || evictedDifference.length > 0,
        retainedDifference,
        evictedDifference
      });
    }
    observations.push({ caseId: fixtureCase.id, paired });
  }

  const componentObserved = observations.some((item) => item.paired.some((pair) => pair.componentObserved));
  if (!componentObserved) {
    throw new Error('Phase-4 component was not observed: retention/eviction sets did not differ');
  }

  const metrics = summarize(observations, fixture.preregistration);
  return {
    schemaVersion: 1,
    experiment: 'E02-phase-4-type-aware-eviction-paired-ablation',
    fixtureSha256: sha256(canonicalJson(fixture)),
    seed: options.seed,
    repetitions: options.repetitions,
    caseCount: cases.length,
    conditions,
    componentObserved,
    preregistration: fixture.preregistration,
    metrics,
    observations,
    notes: [
      'Baseline is Phase-4 FIFO and treatment is Phase-4 type-aware eviction.',
      'Each condition uses an isolated real RuntimeMemoryStore and the same paired seed.',
      'This is an internal, opt-in evaluation; it does not change product defaults, locks, or approvals.'
    ]
  };
}

export async function loadFixture(path = DEFAULT_FIXTURE) {
  const fixture = JSON.parse(await readFile(path, 'utf8'));
  validateFixture(fixture);
  return fixture;
}

export function summarize(observations, preregistration = {}) {
  const definitions = preregistration.metrics ?? [
    { id: 'success', direction: 'higher' },
    { id: 'passAtK', direction: 'higher' },
    { id: 'latencyP50Ms', direction: 'lower' },
    { id: 'latencyP95Ms', direction: 'lower' },
    { id: 'tokensProxy', direction: 'lower' },
    { id: 'falseIntercepts', direction: 'lower' },
    { id: 'safetyViolations', direction: 'lower' }
  ];
  const result = {};
  for (const definition of definitions) {
    const values = observations.flatMap((item) => item.paired.map((pair) => ({
      baseline: pair.baseline.metrics[definition.id],
      treatment: pair.treatment.metrics[definition.id],
      delta: pair.treatment.metrics[definition.id] - pair.baseline.metrics[definition.id]
    }))).filter((item) => Number.isFinite(item.baseline) && Number.isFinite(item.treatment));
    const deltas = values.map((item) => item.delta);
    const baselineValues = values.map((item) => item.baseline);
    const treatmentValues = values.map((item) => item.treatment);
    result[definition.id] = {
      direction: definition.direction,
      baseline: distribution(baselineValues),
      treatment: distribution(treatmentValues),
      pairedEffect: effectSummary(deltas, definition.direction)
    };
  }
  return result;
}

export function deriveSeed(seed, caseIndex, repetition) {
  const digest = createHash('sha256').update(`${seed}:${caseIndex}:${repetition}`).digest();
  return digest.readUInt32BE(0);
}

async function runCondition(options) {
  const { condition, fixtureCase, seed } = options;
  const store = await options.createStore({ isolated: true, seed, condition });
  const eviction = options.eviction[condition];
  const retained = [];
  const evicted = [];
  const inserts = [];
  const start = options.clock?.now() ?? performance.now();
  for (const item of fixtureCase.insertions) {
    const insertStart = options.clock?.now() ?? performance.now();
    const accepted = await options.insert(store, item);
    const insertEnd = options.clock?.now() ?? performance.now();
    inserts.push({ itemId: item.id, accepted: Boolean(accepted), latencyMs: insertEnd - insertStart });
    const removed = await eviction(store, item, { seed });
    for (const id of normalizeIds(removed)) evicted.push(id);
  }
  const retainedIds = await options.listRetained(store);
  retained.push(...retainedIds);
  const end = options.clock?.now() ?? performance.now();
  const expected = new Set(fixtureCase.expectedRetained ?? []);
  const actual = new Set(retainedIds);
  const success = expected.size === actual.size && [...expected].every((id) => actual.has(id));
  const latencies = inserts.map((item) => item.latencyMs).sort((a, b) => a - b);
  const metrics = {
    success: success ? 1 : 0,
    passAtK: fixtureCase.passAtK?.every((k) => success) ? 1 : 0,
    latencyP50Ms: percentile(latencies, 0.5),
    latencyP95Ms: percentile(latencies, 0.95),
    tokensProxy: fixtureCase.tokensProxy ?? 0,
    falseIntercepts: fixtureCase.falseIntercepts ?? 0,
    safetyViolations: fixtureCase.safetyViolations ?? 0,
    totalLatencyMs: end - start
  };
  return { metrics, retained: retainedIds, evicted: [...new Set(evicted)], inserts };
}

function validateOptions(options) {
  if (!options || typeof options !== 'object') throw new TypeError('options are required');
  if (typeof options.createStore !== 'function') throw new TypeError('createStore must construct a RuntimeMemoryStore');
  if (typeof options.insert !== 'function') throw new TypeError('insert must insert into RuntimeMemoryStore');
  if (typeof options.listRetained !== 'function') throw new TypeError('listRetained must inspect RuntimeMemoryStore');
  if (!options.eviction || typeof options.eviction.baseline !== 'function' || typeof options.eviction.treatment !== 'function') {
    throw new TypeError('both baseline FIFO and treatment type-aware eviction functions are required');
  }
  if (!Number.isInteger(options.repetitions) || options.repetitions < 1) throw new TypeError('repetitions must be a positive integer');
  if (!Number.isInteger(options.seed)) throw new TypeError('seed must be an integer');
}

function validateFixture(fixture) {
  if (!fixture || !Array.isArray(fixture.cases) || fixture.cases.length < 20) {
    throw new Error('fixture must contain at least 20 cases');
  }
  const ids = new Set();
  for (const item of fixture.cases) {
    if (!item.id || ids.has(item.id)) throw new Error('fixture case ids must be unique and non-empty');
    ids.add(item.id);
    if (!Array.isArray(item.insertions) || item.insertions.length === 0) throw new Error(`case ${item.id} has no insertions`);
    const insertionIds = item.insertions.map((entry) => entry.id);
    if (new Set(insertionIds).size !== insertionIds.length) throw new Error(`case ${item.id} has duplicate insertion ids`);
  }
  if (!fixture.preregistration?.primaryMetric) throw new Error('fixture must preregister a primary metric');
  if (!Array.isArray(fixture.preregistration?.regressionBudget)) throw new Error('fixture must preregister regression budgets');
}

function normalizeIds(value) {
  if (value == null) return [];
  if (Array.isArray(value)) return value.map(String);
  if (value instanceof Set) return [...value].map(String);
  if (typeof value === 'object') return Object.keys(value).map(String);
  return [String(value)];
}

function difference(left, right) {
  const rightSet = new Set(right.map(String));
  return [...new Set(left.map(String))].filter((id) => !rightSet.has(id)).sort();
}

function percentile(values, fraction) {
  if (!values.length) return 0;
  const position = (values.length - 1) * fraction;
  const lower = Math.floor(position);
  const upper = Math.ceil(position);
  return values[lower] + (values[upper] - values[lower]) * (position - lower);
}

function distribution(values) {
  if (!values.length) return { n: 0, mean: 0, p50: 0, p95: 0 };
  const sorted = [...values].sort((a, b) => a - b);
  const mean = values.reduce((sum, value) => sum + value, 0) / values.length;
  return { n: values.length, mean, p50: percentile(sorted, 0.5), p95: percentile(sorted, 0.95) };
}

function effectSummary(deltas, direction) {
  const mean = deltas.length ? deltas.reduce((sum, value) => sum + value, 0) / deltas.length : 0;
  const median = percentile([...deltas].sort((a, b) => a - b), 0.5);
  const interval = bootstrapInterval(deltas);
  const standardized = standardEffect(deltas);
  const favorable = direction === 'lower' ? mean < 0 : mean > 0;
  return {
    definition: direction === 'lower' ? 'treatment - baseline (negative favors treatment)' : 'treatment - baseline (positive favors treatment)',
    meanDelta: mean,
    medianDelta: median,
    confidence95: interval,
    standardizedEffect: standardized,
    favorable,
    interpretation: mean === 0 ? 'zero effect' : (favorable ? 'favors treatment' : 'does not favor treatment')
  };
}

function standardEffect(deltas) {
  if (deltas.length < 2) return 0;
  const mean = deltas.reduce((sum, value) => sum + value, 0) / deltas.length;
  const variance = deltas.reduce((sum, value) => sum + (value - mean) ** 2, 0) / (deltas.length - 1);
  const sd = Math.sqrt(variance);
  return sd === 0 ? 0 : mean / sd;
}

function bootstrapInterval(values) {
  if (!values.length) return [0, 0];
  if (values.length === 1) return [values[0], values[0]];
  const means = [];
  for (let iteration = 0; iteration < 2000; iteration += 1) {
    let sum = 0;
    for (let index = 0; index < values.length; index += 1) {
      sum += values[Math.floor((iteration * 2654435761 + index * 2246822519) % values.length)];
    }
    means.push(sum / values.length);
  }
  means.sort((a, b) => a - b);
  return [percentile(means, 0.025), percentile(means, 0.975)];
}

function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

function sha256(value) {
  return createHash('sha256').update(value).digest('hex');
}
